886	      // Normalize line endings and split
887	      const rawLines = pasteText.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
888	
889	      // Remove trailing empty lines
890	      while (rawLines.length && rawLines[rawLines.length - 1].trim() === '') rawLines.pop();
891	
892	      // If only one line, let the default paste behavior handle it (single value)
893	      if (rawLines.length <= 1) return;
