97	// ============================================================
98	// LOLM 算法
99	// ============================================================
100	function computeLOLM(rawData) {
101	  const hasLanes = gameConfig.hasLanes;
102	  const lanes = {};
103	  const allHeroes = [];
104	
105	  for (const laneCfg of gameConfig.lanes) {
106	    const raw = rawData[laneCfg.name];
107	    if (!raw) continue;
108	    const heroes = raw.map(h => ({
109	      name: h.heroName,
110	      lane: laneCfg.name,
111	      headIcon: gameConfig.headIconPath ? (gameConfig.gameId + "/" + gameConfig.headIconPath.replace("{name}", h.heroName)) : null,
112	      wr: parsePct(h.winRate),
113	      pr: parsePct(h.pickRate),
114	      br: parsePct(h.banRate),
115	      bp: parsePct(h.pickRate) + parsePct(h.banRate)
116	    }));
117	    lanes[laneCfg.name] = heroes;
118	    allHeroes.push(...heroes);
119	  }
120	
121	  // Z-score 加权（分路内计算 Z-score）
122	  for (const [laneName, heroes] of Object.entries(lanes)) {
123	    const zWr = zScores(heroes.map(h => h.wr));
124	    const zPr = zScores(heroes.map(h => h.pr));
125	    const zBr = zScores(heroes.map(h => h.br));
126	    heroes.forEach((h, i) => {
127	      h.z_wr = zWr[i]; h.z_pr = zPr[i]; h.z_br = zBr[i];
128	      h.raw_zscore = 0.5 * zWr[i] + 1.0 * zPr[i] + 3.0 * zBr[i];
129	    });
130	  }
131	
132	  // 简易公式
133	  for (const [laneName, heroes] of Object.entries(lanes)) {
134	    heroes.forEach(h => {
135	      h.raw_simple = Math.pow(h.wr, 0.3) * (h.pr + 2.5 * h.br) * 100;
136	    });
137	  }
138	
139	  // 分路内 min-max 归一化
140	  function normalize(heroes, rawKey, normKey) {
141	    const vals = heroes.map(h => h[rawKey]);
142	    const lo = Math.min(...vals), hi = Math.max(...vals);
143	    const rng = hi - lo || 1;
144	    heroes.forEach(h => { h[normKey] = ((h[rawKey] - lo) / rng) * 100; });
145	  }
146	
147	  for (const [, heroes] of Object.entries(lanes)) {
148	    normalize(heroes, "raw_zscore", "score_zscore");
149	    normalize(heroes, "raw_simple", "score_simple");
150	  }
151	
152	  // 全局归一化
153	  normalize(allHeroes, "raw_zscore", "score_zscore_global");
154	  normalize(allHeroes, "raw_simple", "score_simple_global");
155	
156	  // 分配梯度
157	  for (const [, heroes] of Object.entries(lanes)) {
158	    assignTiersWithKey(heroes, "score_zscore", "tier_zscore");
159	    assignTiersWithKey(heroes, "score_simple", "tier_simple");
160	    assignTiersWithKey(heroes, "score_zscore_global", "tier_global");
161	  }
162	
163	  function assignTiersWithKey(heroes, scoreKey, tierKey) {
164	    const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
165	    const n = sorted.length;
166	    const thresholds = getTierThresholds();
167	    sorted.forEach((h, i) => {
168	      const pct = 1 - i / n;
169	      let tier = "T4";
170	      for (const t of thresholds) {
171	        if (pct >= t.pct) { tier = t.tier; break; }
172	      }
173	      h[tierKey] = tier;
174	      // Store lane rank under a consistent key: _rank_zscore / _rank_simple
175	      if (tierKey === "tier_zscore") h._rank_zscore = i + 1;
176	      if (tierKey === "tier_simple") h._rank_simple = i + 1;
177	    });
178	  }
179	
180	  // 全局排名
181	  const globalZ = [...allHeroes].sort((a, b) => b.score_zscore_global - a.score_zscore_global);
182	  globalZ.forEach((h, i) => { h.global_rank_zscore = i + 1; });
183	  const globalSimple = [...allHeroes].sort((a, b) => b.score_simple_global - a.score_simple_global);
184	  globalSimple.forEach((h, i) => { h.global_rank_simple = i + 1; });
185	
186	  return { lanes, allHeroes, globalZ, globalSimple };
187	}
188	
189	// ============================================================
190	// 曙光英雄算法（从 Python validate_pure.py 移植）
191	// ============================================================
192	function computeSG(rawData) {
193	  const heroes = rawData.map(h => ({
194	    name: h.heroName,
195	    headIcon: gameConfig.headIconPath ? ("曙光英雄/" + gameConfig.headIconPath.replace("{name}", h.heroName)) : null,
196	    appearanceRank: parseInt(h.appearanceRank),
197	    combatPower: parseFloat(h.combatPower),
198	    winRate: parseFloat(String(h.winRate).replace("%", "")) / 100,
199	    lane: null
200	  }));
201	
202	  const N = heroes.length;
203	  const weights = gameConfig.algorithm.weights;
204	
205	  // 出场分：rank 越小越好，转换为 1 → 1.0, N → 0.0
206	  const appearanceScores = heroes.map(h => 1 - (h.appearanceRank - 1) / (N - 1));
207	
208	  // 战力分 min-max 归一化
209	  const combatVals = heroes.map(h => h.combatPower);
210	  const combatMin = Math.min(...combatVals), combatMax = Math.max(...combatVals);
211	  const combatRange = combatMax - combatMin || 1;
212	  const combatScores = combatVals.map(v => (v - combatMin) / combatRange);
213	
214	  // 胜率 min-max 归一化
215	  const wrVals = heroes.map(h => h.winRate);
216	  const wrMin = Math.min(...wrVals), wrMax = Math.max(...wrVals);
217	  const wrRange = wrMax - wrMin || 1;
218	  const wrScores = wrVals.map(v => (v - wrMin) / wrRange);
219	
220	  // 加权和
221	  heroes.forEach((h, i) => {
222	    h.raw_weighted = weights.appearance * appearanceScores[i]
223	                   + weights.combat * combatScores[i]
224	                   + weights.winrate * wrScores[i];
225	  });
226	
227	  // 最终 min-max 归一化 → 0~100
228	  const rawVals = heroes.map(h => h.raw_weighted);
229	  const rawMin = Math.min(...rawVals), rawMax = Math.max(...rawVals);
230	  const rawRange = rawMax - rawMin || 1;
231	  heroes.forEach(h => { h.score = ((h.raw_weighted - rawMin) / rawRange) * 100; });
232	
233	  // 分配梯度
234	  const sorted = [...heroes].sort((a, b) => b.score - a.score);
235	  const thresholds = getTierThresholds();
236	  sorted.forEach((h, i) => {
237	    const pct = 1 - i / N;
238	    let tier = "T4";
239	    for (const t of thresholds) {
240	      if (pct >= t.pct) { tier = t.tier; break; }
241	    }
242	    h.tier = tier;
243	    h.rank = i + 1;
244	  });
245	
246	  return { heroes, sorted };
247	}
