// Mark an input (and its td) as dirty when the user types
function markDirty(input) {
  const td = input.closest('td');
  if (td) td.classList.add('modified');
  updateSaveState();
}

// Check if any input differs from its data-original value
function hasUnsavedChanges() {
  const inputs = $('tableBody').querySelectorAll('input');
  for (const inp of inputs) {
    if (inp.dataset.col && inp.value.trim() !== (inp.dataset.original || '')) return true;
  }
  return false;
}

// Enable/disable save-related UI based on dirty state
function updateSaveState() {
  const dirty = hasUnsavedChanges();
  $('applyBtn').disabled = !dirty;
  $('applyBtn').style.opacity = dirty ? '1' : '0.4';
}

